def anti_shuffle(s):
    def sort_chars(word):
        return ''.join(sorted(word))

    words = s.split(' ')
    ordered_words = []

    for word in words:
        if word.strip():  # Check if the word is not just spaces
            ordered_words.append(sort_chars(word))
        else:
            ordered_words.append(word)  # Keep the empty space as is

    return ' '.join(ordered_words)
